-- Test stores, riders, items (with photos in /seed), featured items and the opening-ad video.
-- Every id starts with test_. Remove it all with supabase/seed/remove_test_data.sql.
begin;
alter table public.items disable trigger items_guard;
alter table public.rider_bank_accounts disable trigger rider_bank_guard;
update public.platform_settings set ad_enabled = true, ad_media_url = 'https://maldexpress.github.io/maldexpress-app/seed/maldexpress-test-ad.mp4', ad_media_type = 'video', ad_link = null, ad_seconds = 10, ad_skip_after = 5 where id = 1;
alter table public.items enable trigger items_guard;
alter table public.rider_bank_accounts enable trigger rider_bank_guard;
select (select count(*) from businesses where id like 'test_%') stores, (select count(*) from items where id like 'test_%') items, (select count(*) from items where id like 'test_%' and featured_until > now()) featured, (select count(*) from delivery_persons where id like 'test_%') riders, (select count(*) from rider_bank_accounts where rider_id like 'test_%') rider_banks, (select ad_enabled from platform_settings) ad;
commit;
